class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        freq[0] = 1;
        int p = 0, count = 0;
        for (int x : nums) {
            p += x;
            auto it = freq.find(p - k);
            if (it != freq.end()) count += it->second;
            freq[p]++;
        }
        return count;
    }
};
